CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, phone_number VARCHAR(20) NOT NULL UNIQUE, name VARCHAR(120), language ENUM('en','sn','nd') NOT NULL DEFAULT 'en', due_date DATE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE appointments (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, appointment_date DATE NOT NULL, reminder_sent BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE conversation_messages (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NULL, channel VARCHAR(30) NOT NULL, direction ENUM('inbound','outbound') NOT NULL, text TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
